{
  "assessments": [
    {
      "proposition_id": "P1",
      "status": "full",
      "summary_quote": "To count toward the requirement in subsection (a)(1), physical activity would have to include unstructured outdoor play unless weather makes outdoor activity impractical.",
      "rationale": "Conveys the outdoor unstructured-play requirement, its application to qualifying physical activity, and the weather exception."
    },
    {
      "proposition_id": "P2",
      "status": "full",
      "summary_quote": "Time when a student is allowed to use an electronic device, and time in physical education class, would not count as physical activity for this purpose.",
      "rationale": "Expressly excludes time when electronic-device use is permitted from qualifying physical activity."
    },
    {
      "proposition_id": "P3",
      "status": "full",
      "summary_quote": "Time when a student is allowed to use an electronic device, and time in physical education class, would not count as physical activity for this purpose.",
      "rationale": "Expressly excludes time spent in physical education class from qualifying physical activity."
    },
    {
      "proposition_id": "P4",
      "status": "full",
      "summary_quote": "A student could be denied the privilege of taking part in physical activity for conduct that violates the school or district discipline policy or code of conduct, or for violent, threatening, or other behavior that significantly disrupts or impairs other students’ ability to take part and benefit. A teacher or administrator could remove or deny the student’s participation as discipline",
      "rationale": "Covers the grounds for exclusion and teachers’ or administrators’ authority to remove students or deny participation as discipline."
    },
    {
      "proposition_id": "P5",
      "status": "full",
      "summary_quote": "A teacher or administrator could remove or deny the student’s participation as discipline and could assign alternative lessons, assignments, or activities—including physical activities—to improve the student’s conduct or behavior.",
      "rationale": "Conveys who may assign alternatives, links that authority to disciplinary exclusion, and includes the permitted alternatives and behavioral-improvement purpose."
    },
    {
      "proposition_id": "P6",
      "status": "full",
      "summary_quote": "The bill would take effect when it becomes law.",
      "rationale": "Accurately states the effective-date provision."
    }
  ]
}
